function playChime(){if(!ui.sound)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const now=audioContext.currentTime;for(const [i,f] of [523.25,659.25,783.99].entries()){const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.value=f;gain.gain.setValueAtTime(0,now+i*.065);gain.gain.linearRampToValueAtTime(.035,now+i*.065+.012);gain.gain.exponentialRampToValueAtTime(.001,now+i*.065+.23);osc.connect(gain);gain.connect(audioContext.destination);osc.start(now+i*.065);osc.stop(now+i*.065+.24);}}catch{}}
function toast(text,error=false,onClick=null){const node=document.createElement('div');node.className='toast'+(error?' error':' success')+(onClick?' clickable':'');node.textContent=text;if(onClick){node.setAttribute('role','button');node.onclick=()=>{node.remove();onClick();};}$('toasts').appendChild(node);setTimeout(()=>node.remove(),5500);while($('toasts').children.length>3)$('toasts').firstChild.remove();}
function save(manual=false){try{const data=serializeGame(state);const previous=localStorage.getItem(saveKey);if(previous){try{deserializeGame(previous);localStorage.setItem(backupKey,previous);}catch{localStorage.setItem(saveKey+':corrupt',previous);}}localStorage.setItem(saveKey,data);localStorage.setItem(seenKey,String(Date.now()));saveFailure='';$('save-status').textContent='บันทึกแล้ว · '+new Date().toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit'});if(manual)toast('บันทึกกิลด์เรียบร้อย');return true;}catch(error){saveFailure='บันทึกอัตโนมัติไม่ได้ กรุณาส่งออกไฟล์เซฟ';$('save-status').textContent='⚠ '+saveFailure;if(manual)toast(saveFailure,true);return false;}}
