function portrait(member,extra=''){return `<canvas class="portrait" width="64" height="72" data-portrait="${h(member.id)}" ${extra}></canvas>`;}
function itemIcon(id){return `<canvas class="item-icon" width="40" height="40" data-item="${h(id)}"></canvas>`;}
function injectIcons(root=document){drawCodexMonsters(root);root.querySelectorAll('canvas[data-portrait]').forEach(c=>{const m=state.members.find(m=>m.id===c.dataset.portrait)||MEMBERS.find(m=>m.id===c.dataset.portrait);if(m)drawPortrait(c,m,64);});root.querySelectorAll('canvas[data-applicant]').forEach(c=>{const a=(state.applicants||[]).find(a=>a.id===c.dataset.applicant);if(a)drawPortrait(c,applicantLook(a),64);});root.querySelectorAll('canvas[data-villager]').forEach(c=>{const p=(state.petitions||[]).find(p=>p.id===c.dataset.villager);if(p)drawPortrait(c,villagerLook(p),64);});root.querySelectorAll('canvas[data-item]').forEach(c=>drawItemIcon(c,item(c.dataset.item)||c.dataset.item,40));root.querySelectorAll('canvas[data-furniture]').forEach(c=>drawFurniture(c,c.dataset.furniture));root.querySelectorAll('canvas[data-quest-art]').forEach(c=>drawQuestArt(c,QUESTS.find(q=>q.id===c.dataset.questArt)||{},{locked:'locked'in c.dataset}));root.querySelectorAll('canvas[data-region-art]').forEach(c=>drawQuestArt(c,{},{region:c.dataset.regionArt,locked:'locked'in c.dataset}));}
// Shop preview: the same isometric furniture sprites the scene uses, fitted into the card.
function drawFurniture(canvas,type){let parts;try{parts=makeRoom({id:'preview',type,x:0,y:0,rotation:0,level:1}).layers.map(part=>{const p=gridPoint(part.x,part.y);return{c:part.sprite.canvas,x:p.x-part.sprite.footX,y:p.y-part.sprite.footY,sort:p.y+part.sort};}).sort((a,b)=>a.sort-b.sort);}catch{return;}if(!parts.length)return;const minX=Math.min(...parts.map(p=>p.x)),minY=Math.min(...parts.map(p=>p.y)),maxX=Math.max(...parts.map(p=>p.x+p.c.width)),maxY=Math.max(...parts.map(p=>p.y+p.c.height));const ctx=canvas.getContext('2d'),w=canvas.width,hh=canvas.height,scale=Math.max(1,Math.min(4,Math.floor(Math.min((w-10)/(maxX-minX),(hh-10)/(maxY-minY)))));ctx.clearRect(0,0,w,hh);ctx.imageSmoothingEnabled=false;const ox=(w-(maxX-minX)*scale)/2,oy=(hh-(maxY-minY)*scale)/2;for(const p of parts)ctx.drawImage(p.c,Math.round(ox+(p.x-minX)*scale),Math.round(oy+(p.y-minY)*scale),Math.round(p.c.width*scale),Math.round(p.c.height*scale));}
function missionRatio(m){return Math.max(0,Math.min(1,(m.progress||0)/(m.duration||1)));}
function missionEventPending(m){return m.event&&!m.event.resolved;}
function taskText(m){if(m.errand)return errandText(m);if(isAway(m.id))return'ออกภารกิจ';if(m.injury>0)return'พักรักษา';return({rest:'พักฟื้น',train:'ฝึกฝน',work:'ช่วยงาน',auto:'เตรียมพร้อม'})[m.task]||'พักฟื้น';}
