$('import-file').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;if(file.size>2000000){toast('ไฟล์เซฟใหญ่เกินไป',true);return;}try{const imported=deserializeGame(await file.text());$('settings-dialog').close();confirmAction('ใช้เซฟจากไฟล์นี้?',`กิลด์ระดับ ${imported.rank} วันที่ ${imported.day} · ข้อมูลปัจจุบันจะถูกแทนที่`,()=>{state=imported;state.settings.paused=false;ui={...ui,tab:'quests',region:'meadow',questId:null,memberId:null,missionId:null,facilityId:null,selected:new Set(),paused:false,speed:state.settings.speed||1,sound:!!state.settings.sound,tutorial:!state.completedQuests?.patrol};cancelBuild();renderer?.setState(state);renderer?.resetView?.();seenLog=state.log[0];save();syncUI();toast('นำเข้ากิลด์เรียบร้อย');});}catch(error){toast('ไฟล์เซฟไม่ถูกต้องหรือไม่รองรับ ข้อมูลปัจจุบันยังอยู่',true);}});
document.addEventListener('click',event=>{const b=event.target.closest('button,[role="button"]');if(!b||b.disabled)return;const d=b.dataset;if(d.tab){navigate(d.tab);return;}if(d.region){ui.region=d.region;syncUI();return;}if(d.quest){ui.questId=d.quest;ui.petitionId=d.petId||null;ui.missionId=null;ui.selected.clear();syncUI();return;}if(d.member){ui.memberId=d.member;ui.tab='members';syncUI();return;}if(d.facility){ui.partitionId=null;ui.facilityId=d.facility;ui.tab='build';syncUI();return;}if(d.openMission){openMenu();ui.tab='quests';ui.missionId=d.openMission;ui.questId=null;syncUI();return;}if('back'in d){ui.villageBuildingId=null;ui.partitionId=null;ui.petitionId=null;ui.roomDraftW=null;ui.roomDraftH=null;ui.questId=null;ui.memberId=null;ui.facilityId=null;ui.missionId=null;ui.selected.clear();syncUI();return;}if(d.eventChoice){dispatch('chooseEvent',{missionId:d.mission,choiceId:d.eventChoice});return;}if(d.recall){confirmAction('เรียกทีมกลับ?', 'ทีมจะหยุดภารกิจและกลับมาพักที่กิลด์',()=>dispatch('recallMission',{missionId:d.recall}));return;}if(d.recruit){dispatch('recruit',{memberId:d.recruit});return;}if(d.task){dispatch('setTask',{memberId:d.memberId,task:d.task});return;}if(d.build){cancelBuild();ui.buildType=d.build;ui.moveId=null;ui.facilityId=null;renderer?.setMoveMode(null);renderer?.setBuildMode(d.build);closeMenu();syncUI();return;}if(d.roomType){if(!$('room-width').reportValidity()||!$('room-height').reportValidity())return;const room={type:d.roomType,width:Number($('room-width').value),height:Number($('room-height').value),rotation:0};cancelBuild();ui.facilityId=null;ui.partitionId=null;ui.roomPlacement=room;renderer?.setRoomMode(room);closeMenu();syncHUD();return;}if(d.partition){ui.facilityId=null;ui.partitionId=d.partition;ui.roomDraftW=null;ui.roomDraftH=null;ui.tab='build';syncUI();return;}if(d.moveRoom){const room=state.rooms.find(r=>r.id===d.moveRoom);cancelBuild();ui.moveRoomId=room.id;renderer?.setRoomMode(room,room.id);closeMenu();syncHUD();return;}if(d.rotateRoom){dispatch('rotateRoom',{roomId:d.rotateRoom});return;}if(d.resizeRoom){const inputs=[...document.querySelectorAll('[data-partition-size]')];if(inputs.some(i=>!i.reportValidity()))return;dispatch('resizeRoom',{roomId:d.resizeRoom,width:Number(inputs.find(i=>i.dataset.partitionSize==='width').value),height:Number(inputs.find(i=>i.dataset.partitionSize==='height').value)});return;}if(d.demolishRoom){confirmAction('รื้อผนังห้อง?', 'ของภายในจะอยู่บนพื้นที่โล่ง ได้วัสดุคืนบางส่วน',()=>{if(dispatch('demolishRoom',{roomId:d.demolishRoom})){ui.partitionId=null;syncUI();}});return;}if('cancelBuild'in d){cancelBuild();return;}if(d.rotate){dispatch('rotate',{facilityId:d.rotate});return;}if('rotatePlacement'in d){if(ui.villagePlace)renderer?.rotateVillagePick();else renderer?.rotatePlacement();syncHUD();return;}if('expandBuilding'in d){confirmAction('ต่อเติมอาคาร?',moneyCost(getBuildingExpansionCost(state)),()=>dispatch('expandBuilding'));return;}if(d.move){cancelBuild();ui.moveId=d.move;ui.buildType=null;renderer?.setBuildMode(null);renderer?.setMoveMode(d.move);closeMenu();syncHUD();return;}if(d.upgrade){const f=state.facilities.find(f=>f.id===d.upgrade);const def=FACILITIES[f.type];const cost=getUpgradeCost(state,f.id);confirmAction('อัปเกรด'+def.name,`ปรับปรุงเป็นระดับ ${f.level+1} · ${moneyCost(cost)}`,()=>dispatch('upgrade',{facilityId:d.upgrade}));return;}if(d.demolish){confirmAction('รื้อของชิ้นนี้?', 'พื้นที่จะว่างให้จัดวางใหม่ ได้ทรัพยากรคืนบางส่วน ความจุและโบนัสจะลดลง',()=>{if(dispatch('demolish',{facilityId:d.demolish})){ui.facilityId=null;syncUI();}});return;}if('expand'in d){confirmAction('ขยายที่ดินกิลด์?',`${state.grid.width+6}×${state.grid.height+4} ช่อง · ${moneyCost(getExpansionCost(state))}`,()=>dispatch('expand'));return;}if(d.craft){dispatch('craft',{equipmentId:d.craft});return;}if(d.equip){const select=document.querySelector(`[data-equip-select="${CSS.escape(d.equip)}"]`);if(select)dispatch('equip',{memberId:select.value,equipmentId:d.equip});return;}if(d.unequip){dispatch('equip',{memberId:d.memberId,equipmentId:null,slot:d.unequip});return;}if(d.specialize){confirmAction('เปลี่ยนเป็น'+JOBS[d.specialize].name+'?', 'สมาชิกจะไปทำพิธีที่โรงฝึก (40 วินาที) ค่าพิธีจ่ายจากเงินส่วนตัวก่อน ขาดเท่าไรกิลด์ออกให้ · เลือกสายแล้วเปลี่ยนกลับไม่ได้',()=>dispatch('specialize',{memberId:d.memberId,classId:d.specialize}));return;}if(d.hostEvent){dispatch('hostEvent',{eventId:d.hostEvent});return;}if(d.speed){if(heroOn()&&Number(d.speed)!==1){toast('ตอนออกไปเองใช้ได้แค่ความเร็ว ×1',true);return;}ui.speed=Number(d.speed);state.settings.speed=ui.speed;ui.paused=false;syncHUD();save();return;}if('dismissTutorial'in d){ui.tutorial=false;syncUI();return;}if('saveNow'in d){save(true);return;}if('exportSave'in d){const blob=new Blob([serializeGame(state)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`little-leaf-guild-day-${state.day}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('ส่งออกไฟล์เซฟแล้ว');return;}if('importSave'in d){$('import-file').click();return;}if('toggleMusic'in d){state.settings.music=state.settings.music===false;setAudio({music:state.settings.music});save();openSettings();return;}if('toggleSound'in d){ui.sound=!ui.sound;state.settings.sound=ui.sound;setAudio({sfx:ui.sound});save();playChime();b.textContent=ui.sound?'♪ เสียงเปิด':'♪ เสียงปิด';return;}if('newGame'in d){$('settings-dialog').close();confirmAction('เริ่มกิลด์ใหม่?', 'เซฟปัจจุบันจะถูกแทนที่ เริ่มจากบ้านว่างหลังแรก',()=>{closeMenu();showTitle();openSetup('new');});}});
