 if($('hero-pack').__h!==pack){$('hero-pack').textContent=pack;$('hero-pack').__h=pack;}if($('hero-jobs').__h!==jobs){$('hero-jobs').innerHTML=jobs;$('hero-jobs').__h=jobs;}
