heroPress('hero-attack',on=>{heroAttackHeld=on;});for(const [id,key] of [['hero-s1','s1'],['hero-s2','s2'],['hero-ult','ult'],['hero-dash','dash'],['hero-act','act']])heroPress(id,on=>{if(on)heroTap(key);});
