 if(step==='reception')return{label:'บทนำ 1/5',title:'วางโต๊ะรับคำร้อง',meta:`ที่รับงานจากชาวบ้าน · แตะที่นี่แล้วแตะพื้นในบ้าน · ${cost('reception')}`,action:'build:reception',urgent:true};
 if(step==='board')return{label:'บทนำ 2/5',title:'วางกระดานคำร้อง',meta:`นักผจญภัยจะมาเลือกงานและจับกลุ่มกันเองที่นี่ · ${cost('board')}`,action:'build:board',urgent:true};
 if(step==='training')return{label:'บทนำ 3/5',title:'วางหุ่นฝึก',meta:`ให้มิราฝึกฝีมือ แล้วข่าวจะไปถึงคนอื่น · ${cost('training')}`,action:'build:training',urgent:true};
 if(step==='wait')return{label:'บทนำ',title:'รอคนมาเคาะประตู…',meta:'ข่าวว่ากิลด์เปิดแล้วกำลังแพร่ไปในหมู่บ้าน',progress:Math.min(1,state.intro.timer/(state.intro.delay||6)),action:'none'};
